/* Hidden-object levels. Coordinates mark actual furniture surfaces in each room. */
const searchLevels={easy:{name:'Fácil',total:12,goal:3,perGroup:2,offset:6},medium:{name:'Médio',total:20,goal:5,perGroup:2,offset:3.6},hard:{name:'Difícil',total:30,goal:8,perGroup:3,offset:2.4}};
let searchLevel='easy',searchRun=0;
const SEARCH_DURATION=60000;
let searchDeadline=0,searchTimer=null,searchExpired=false;
function stopSearchTimer(){if(searchTimer!==null)cancelAnimationFrame(searchTimer);searchTimer=null;searchDeadline=0}
function expireSearch(){if(searchExpired||won)return;searchExpired=true;stopSearchTimer();const bar=$('#search-time-fill'),clock=$('#search-seconds'),track=$('#search-time');if(bar)bar.style.transform='scaleX(0)';if(clock)clock.textContent='0:00';if(track)track.setAttribute('aria-valuenow','0');document.querySelectorAll('.search-toy').forEach(b=>b.disabled=true);if($('#hint'))$('#hint').disabled=true;const board=$('#board');if(!board)return;board.insertAdjacentHTML('beforeend',`<div class="win time-up" role="status"><h2>O tempo acabou!</h2><p>Você encontrou ${targets.filter(id=>items.find(i=>i.uid===id).found).length} de ${targets.length} amigos. Vamos tentar de novo?</p><button class="action" id="again">Tentar novamente</button></div>`);$('#again').onclick=start;$('#again').focus({preventScroll:true});board.querySelector('.time-up').scrollIntoView({block:'nearest',inline:'center'})}
function tickSearchTimer(){if(!searchDeadline||won||searchExpired)return;if(!$('#search-time')){stopSearchTimer();return}const left=Math.max(0,searchDeadline-Date.now()),seconds=Math.ceil(left/1000);$('#search-time-fill').style.transform=`scaleX(${left/SEARCH_DURATION})`;$('#search-seconds').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;$('#search-time').setAttribute('aria-valuenow',seconds);if(left===0){expireSearch();return}searchTimer=requestAnimationFrame(tickSearchTimer)}
function startSearchTimer(){stopSearchTimer();searchExpired=false;searchDeadline=Date.now()+SEARCH_DURATION;tickSearchTimer()}
function searchTimeAllowsAction(){if(searchExpired||won||!searchDeadline)return false;if(Date.now()>=searchDeadline){expireSearch();return false}return true}
let searchOwnsFullscreen=false;
function enterSearchFullscreen(){if(document.fullscreenElement)return Promise.resolve();try{return Promise.resolve(document.documentElement.requestFullscreen()).then(()=>{searchOwnsFullscreen=true;try{return screen.orientation.lock('landscape').catch(()=>{})}catch{}}).catch(()=>{})}catch{return Promise.resolve()}}
function leaveSearchFullscreen(){if(searchOwnsFullscreen){searchOwnsFullscreen=false;try{screen.orientation.unlock()}catch{}if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})}}
async function showSearchIntro(run){const overlay=$('#search-intro'),label=$('#intro-number');for(const value of ['3','2','1','Já!']){if(run!==searchRun||!overlay?.isConnected)return false;label.textContent=value;await new Promise(resolve=>setTimeout(resolve,value==='Já!'?550:1000))}if(run!==searchRun||!overlay.isConnected)return false;overlay.remove();$('.search-workspace').classList.remove('preparing');$('#hint').disabled=false;return true}
const toySprites=new Map();
const roomSpots={
 andy:[[38,44,13],[48,46,14],[89,29,12],[94,40,12],[88,50,13],[15,39,12],[68,49,13],[23,75,19],[53,83,21],[78,77,20]],
 buzz:[[23,45,14],[35,47,14],[37,32,12],[82,27,12],[81,42,12],[55,46,12],[66,46,12],[19,79,20],[48,85,21],[76,75,20]],
 bonnie:[[38,40,12],[48,41,12],[58,22,10],[58,35,10],[76,35,11],[11,41,12],[89,44,11],[23,76,20],[51,84,21],[76,76,20]],
 blaze:[[20,44,13],[35,44,13],[43,30,11],[43,37,11],[60,45,12],[73,45,12],[93,40,11],[23,79,20],[52,84,21],[77,78,20]],
 molly:[[39,45,12],[47,45,12],[29,20,10],[90,20,11],[88,45,12],[12,51,13],[28,12,10],[23,81,20],[52,85,21],[77,81,20]]
};
function shuffled(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function loadToySprite(t){if(toySprites.has(t.id))return Promise.resolve(toySprites.get(t.id));return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0);const data=ctx.getImageData(0,0,c.width,c.height).data;let x0=c.width,y0=c.height,x1=0,y1=0;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++)if(data[(y*c.width+x)*4+3]>32){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}const sprite=document.createElement('canvas');sprite.width=180;sprite.height=Math.max(1,Math.round(180*(y1-y0+1)/(x1-x0+1)));sprite.getContext('2d').drawImage(c,x0,y0,x1-x0+1,y1-y0+1,0,0,sprite.width,sprite.height);const mask=sprite.getContext('2d',{willReadFrequently:true}).getImageData(0,0,sprite.width,sprite.height).data;const result={canvas:sprite,mask,ratio:sprite.width/sprite.height};toySprites.set(t.id,result);resolve(result)};img.onerror=()=>reject(new Error(t.name));img.src=t.asset})}
function spriteContains(i,x,y){const s=toySprites.get(i.id),u=(x-(i.x-i.w/2))/i.w,v=(y-(i.y-i.h))/i.h;if(u<0||v<0||u>=1||v>=1)return false;return s.mask[(Math.floor(v*s.canvas.height)*s.canvas.width+Math.floor(u*s.canvas.width))*4+3]>45}
function visibleShare(i,list){let total=0,visible=0;for(let y=0;y<24;y++)for(let x=0;x<24;x++){const px=i.x-i.w/2+(x+.5)*i.w/24,py=i.y-i.h+(y+.5)*i.h/24;if(!spriteContains(i,px,py))continue;total++;if(!list.some(o=>o.z>i.z&&spriteContains(o,px,py)))visible++}return total?visible/total:0}
function makeSearchLayout(pool,level,whichRoom){const cfg=searchLevels[level],spots=roomSpots[whichRoom];return pool.map((t,i)=>{const group=Math.floor(i/cfg.perGroup),depth=i%cfg.perGroup,[x,y,size]=spots[group],ratio=toySprites.get(t.id).ratio;const h=Math.min(size,13/(.563*ratio)),w=h*.563*ratio;return {uid:i,id:t.id,x:Math.max(w/2+1,Math.min(99-w/2,x+(depth-(cfg.perGroup-1)/2)*cfg.offset)),y:Math.max(h+1,Math.min(98,y+depth*.65)),w,h,z:group*4+depth+1,found:false,group}})}
choose=function(){leaveSearchFullscreen();stopSearchTimer();searchRun++;document.body.dataset.section='toys';mode='search';app.innerHTML=`<section class="content"><div class="toolbar"><button class="back" id="back">← Início</button><span class="mini-label">PROCURAR BRINQUEDOS</span></div><h1>Como vamos brincar?</h1><p>Você tem 1 minuto! Escolha a dificuldade e depois o quarto.</p><div class="difficulty-cards" role="group" aria-label="Dificuldade">${Object.entries(searchLevels).map(([key,l])=>`<button data-level="${key}" aria-pressed="${searchLevel===key}"><span>${{easy:'★',medium:'★★',hard:'★★★'}[key]}</span><b>${l.name}</b><small>${l.total} brinquedos · encontrar ${l.goal}</small></button>`).join('')}</div><h2 class="room-prompt">Escolha o quarto</h2><div class="rooms">${roomCards()}</div></section>`;$('#back').onclick=home;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{searchLevel=b.dataset.level;document.querySelectorAll('[data-level]').forEach(v=>v.setAttribute('aria-pressed',v===b))});document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{room=b.dataset.room;start()});window.scrollTo(0,0)};
start=async function(){const fullscreenReady=enterSearchFullscreen();stopSearchTimer();searchExpired=false;const run=++searchRun;mode='search';won=false;document.body.dataset.section='toys';const cfg=searchLevels[searchLevel],pool=shuffled(catalog.filter(t=>t.asset)).slice(0,cfg.total);app.innerHTML='<section class="search-workspace immersive loading-round"><button class="back" id="loading-back">← Voltar</button><div role="status"><h1>Preparando o quarto…</h1><p>Já vamos brincar!</p></div></section>';$('#loading-back').onclick=choose;try{await Promise.all([...pool.map(loadToySprite),new Promise((resolve,reject)=>{const background=new Image();background.onload=resolve;background.onerror=reject;background.src=`assets/${room}.png`})]);if(run!==searchRun||document.body.dataset.section!=='toys')return;items=makeSearchLayout(pool,searchLevel,room);/* Every toy retains a clickable visible piece; retry positions locally if an outline is buried. */for(let attempt=0;attempt<8;attempt++){let changed=false;for(const i of items){if(visibleShare(i,items)<.12){i.x=Math.max(i.w/2+1,i.x-1.3);i.y=Math.max(i.h+1,i.y-.6);changed=true}}if(!changed)break}const eligible=items.filter(i=>visibleShare(i,items)>=.12);const hidden=shuffled(eligible.filter(i=>visibleShare(i,items)<.8));const chosen=searchLevel==='easy'?shuffled(eligible).slice(0,cfg.goal):hidden.slice(0,Math.ceil(cfg.goal*.6));for(const i of shuffled(eligible))if(chosen.length<cfg.goal&&!chosen.includes(i))chosen.push(i);targets=chosen.map(i=>i.uid);await fullscreenReady;if(run!==searchRun)return;renderGame();if(await showSearchIntro(run))startSearchTimer()}catch(e){if(run!==searchRun)return;app.innerHTML='<section class="content"><h1>Não conseguimos carregar os brinquedos.</h1><button class="action" id="retry-toys">Tentar novamente</button></section>';$('#retry-toys').onclick=start}};
renderGame=function(){const r=rooms.find(r=>r.id===room),cfg=searchLevels[searchLevel];app.innerHTML=`<section class="workspace search-workspace immersive preparing"><div id="search-intro" class="search-intro"><div class="intro-copy"><p>Prepare-se!</p><strong id="intro-number" role="status" aria-live="assertive">3</strong></div></div><div class="toolbar"><button class="back" id="back">← Quartos e nível</button><h1>${r.name} <small>· ${cfg.name}</small></h1><div class="controls"><button id="hint" disabled>☀ Pista</button><button id="restart">↻ Misturar</button><button id="search-fullscreen">⛶ Tela cheia</button></div></div><div class="search-countdown"><div class="countdown-label"><span>Tempo para encontrar todos</span><strong id="search-seconds" aria-hidden="true">1:00</strong></div><div id="search-time" class="time-track" role="progressbar" aria-label="Segundos restantes" aria-valuemin="0" aria-valuemax="60" aria-valuenow="60"><div id="search-time-fill"></div></div></div><p class="landscape-tip">↻ Vire o celular para jogar com o quarto na horizontal. Você também pode deslizar o cenário.</p><div class="game-layout"><div class="scene-column"><div class="board-scroll"><div class="board search-board" id="board" aria-label="Quarto interativo"><img src="assets/${room}.png" alt="Quarto de ${r.name}"><div id="pieces"></div></div></div><div class="status">${cfg.total} brinquedos espalhados · encontre ${cfg.goal}. Procure nas prateleiras, na cama e atrás dos outros brinquedos.</div></div><aside class="sidebar" id="sidebar"></aside></div></section>`;$('#back').onclick=()=>{searchRun++;choose()};$('#hint').onclick=hint;$('#restart').onclick=start;$('#search-fullscreen').onclick=async()=>{if(document.fullscreenElement){searchOwnsFullscreen=false;try{screen.orientation.unlock()}catch{}await document.exitFullscreen()}else await enterSearchFullscreen()};draw();window.scrollTo(0,0)};
draw=function(){const pieces=$('#pieces');pieces.innerHTML=items.map(i=>{const t=catalog.find(t=>t.id===i.id);return `<button class="toy image-only search-toy ${i.found?'found':''}" data-uid="${i.uid}" style="left:${i.x}%;top:${i.y}%;width:${i.w}%;height:${i.h}%;z-index:${i.z}" aria-label="${esc(t.name)}" ${i.found?'disabled':''}><canvas aria-hidden="true"></canvas></button>`}).join('');for(const i of items){const button=pieces.querySelector(`[data-uid="${i.uid}"]`),canvas=button.querySelector('canvas'),s=toySprites.get(i.id);canvas.width=s.canvas.width;canvas.height=s.canvas.height;canvas.getContext('2d').drawImage(s.canvas,0,0);button.onclick=e=>{if(e.detail===0)find(i)}}$('#board').onclick=e=>{if(e.detail===0||e.target.closest('.win'))return;const rect=$('#board').getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*100,y=(e.clientY-rect.top)/rect.height*100;const hit=items.filter(i=>!i.found&&spriteContains(i,x,y)).sort((a,b)=>(pieces.querySelector(`[data-uid="${b.uid}"]`).classList.contains('hint')?1000:b.z)-(pieces.querySelector(`[data-uid="${a.uid}"]`).classList.contains('hint')?1000:a.z))[0];if(hit)find(hit)};drawSide()};
find=function(i){if(!searchTimeAllowsAction()||i.found)return;if(!targets.includes(i.uid)){notify('Esse não está na lista. Procure mais um pouquinho!');return}i.found=true;chime();draw();if(targets.every(id=>items.find(i=>i.uid===id).found)){won=true;stopSearchTimer();if($('#hint'))$('#hint').disabled=true;saved.completed={...saved.completed,[room+':'+searchLevel]:true};save();$('#board').insertAdjacentHTML('beforeend',`<div class="win" role="status"><h2>★ Você encontrou todos! ★</h2><p>${searchLevels[searchLevel].name}: ${targets.length} amigos encontrados.</p><button class="action" id="again">Brincar de novo</button></div>`);$('#again').onclick=start}};
drawSide=function(){$('#sidebar').innerHTML=`<h2>Encontre</h2><p aria-live="polite">${targets.filter(id=>items.find(i=>i.uid===id).found).length} / ${targets.length}</p><div class="target-list ${targets.length>5?'many-targets':''}">${targets.map(id=>{const i=items.find(i=>i.uid===id),t=catalog.find(t=>t.id===i.id);return `<div class="target ${i.found?'done':''}" role="img" aria-label="${esc(t.name)}${i.found?' encontrado':''}"><canvas data-target="${id}" aria-hidden="true"></canvas>${i.found?'<span class="target-check" aria-hidden="true">✓</span>':''}</div>`}).join('')}</div>`;document.querySelectorAll('[data-target]').forEach(c=>{const i=items.find(i=>i.uid===+c.dataset.target),sprite=toySprites.get(i.id).canvas;c.width=sprite.width;c.height=sprite.height;c.getContext('2d').drawImage(sprite,0,0)})};
hint=function(){if(!searchTimeAllowsAction())return;const i=items.find(i=>targets.includes(i.uid)&&!i.found);if(!i)return;const b=document.querySelector(`[data-uid="${i.uid}"]`);b.classList.remove('hint');void b.offsetWidth;b.classList.add('hint');setTimeout(()=>b.classList.remove('hint'),3500);b.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});notify('O brilho mostra um amigo da lista!')};

// Cancel the round and pending asset loads when leaving through global navigation.
const searchPreviousHome=home,searchPreviousCatalog=showCatalog,searchPreviousFashion=fashion;
home=function(){leaveSearchFullscreen();stopSearchTimer();searchRun++;return searchPreviousHome()};
showCatalog=function(){leaveSearchFullscreen();stopSearchTimer();searchRun++;return searchPreviousCatalog()};
fashion=function(){leaveSearchFullscreen();stopSearchTimer();searchRun++;return searchPreviousFashion()};
